Repair the complete source below and return a corrected complete source file. Export exactly `{ chooseLighter }`. Each argument must be an array containing only finite, non-negative numbers; malformed input throws `TypeError`. Compare the sums of the arrays. Return a shallow copy of the array with the smaller sum; on equal sums, return a shallow copy of the second array. Preserve element order and duplicates. Empty arrays have sum zero. Do not mutate either input, and never return either input array itself.

```javascript
'use strict';

function chooseLighter(first, second) {
  const valid = list => Array.isArray(list) && list.every(
    value => typeof value === 'number' && Number.isFinite(value) && value >= 0
  );
  if (!valid(first) || !valid(second)) {
    throw new TypeError('arguments must contain finite non-negative numbers');
  }

  const firstTotal = first.reduce((sum, value) => sum + value, 0);
  const secondTotal = second.reduce((sum, value) => sum + value, 0);
  return firstTotal <= secondTotal ? first.slice() : second.slice();
}

module.exports = { chooseLighter };
```

