'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['chooseLighter']);
assert.strictEqual(typeof api.chooseLighter, 'function');

const first = [3, 1, 1];
const second = [2, 4];
const firstSnapshot = first.slice();
const secondSnapshot = second.slice();
const chosenFirst = api.chooseLighter(first, second);
assert.deepStrictEqual(chosenFirst, [3, 1, 1]);
assert.notStrictEqual(chosenFirst, first);
assert.notStrictEqual(chosenFirst, second);
assert.deepStrictEqual(first, firstSnapshot);
assert.deepStrictEqual(second, secondSnapshot);

const heavierFirst = [5, 5];
const lighterSecond = [4, 4, 1];
const chosenSecond = api.chooseLighter(heavierFirst, lighterSecond);
assert.deepStrictEqual(chosenSecond, [4, 4, 1]);
assert.notStrictEqual(chosenSecond, lighterSecond);
assert.notStrictEqual(chosenSecond, heavierFirst);

const equalFirst = [1, 2];
const equalSecond = [3, 0];
const tieResult = api.chooseLighter(equalFirst, equalSecond);
assert.deepStrictEqual(tieResult, equalSecond);
assert.notStrictEqual(tieResult, equalSecond);
assert.notStrictEqual(tieResult, equalFirst);

const emptyFirst = [];
const emptySecond = [];
const emptyTie = api.chooseLighter(emptyFirst, emptySecond);
assert.deepStrictEqual(emptyTie, []);
assert.notStrictEqual(emptyTie, emptySecond);
assert.notStrictEqual(emptyTie, emptyFirst);

assert.deepStrictEqual(api.chooseLighter([], [0.1]), []);
const duplicateResult = api.chooseLighter([1, 1, 1], [4]);
assert.deepStrictEqual(duplicateResult, [1, 1, 1]);

for (const args of [
  [null, []],
  [[], null],
  [{}, []],
  [[], 'values'],
  [[-1], []],
  [[], [-0.1]],
  [[NaN], []],
  [[], [Infinity]],
  [[-Infinity], []],
  [[1, '2'], []],
  [[], [null]]
]) {
  assert.throws(() => api.chooseLighter(...args), TypeError);
}

